import React from 'react';
import DataTable, {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableHeader,
  TableRow,
} from 'carbon-components-react';
import { OverflowMenu, OverflowMenuItem } from 'carbon-components-react';

const initialRows = [
  { id: 'a', protocol: 'HTTP', port: 80 },
  { id: 'b', protocol: 'HTTPS', port: 443 },
  { id: 'c', protocol: 'FTP', port: 21 },
];

const headers = [
  { key: 'protocol', header: 'Protocol' },
  { key: 'port', header: 'Port' },
  { key: 'actions', header: 'Actions' },
];

function App() {
  return (
    <DataTable
      rows={initialRows}
      headers={headers}
      render={({ rows, headers, getHeaderProps, getRowProps }) => (
        <TableContainer title="DataTable with OverflowMenu">
          <Table>
            <TableHead>
              <TableRow>
                {headers.map(header => (
                  <TableHeader {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id} {...getRowProps({ row })}>
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                  <TableCell>
                    <OverflowMenu>
                      <OverflowMenuItem itemText="Option 1" />
                      <OverflowMenuItem itemText="Option 2" />
                      <OverflowMenuItem itemText="Option 3" />
                    </OverflowMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    />
  );
}

export default App;
